{
  "system_name": "campus-bike",
  "functional_requirements": [
    {
      "id": "S1",
      "description": "The biker must be able to register with the app by providing their name, email address, phone number, and selecting a password, and provide Zip code of residential address (optional information). The app must ensure that user information is secured with an end-to-end encryption of information between user device and app database.",
      "patterns": [],
      "priority": 1.0
    },
    {
      "id": "S2",
      "description": "The app must sent a verification code via an SMS or email that is valid for 30 minutes. If the code is not entered within 30 seconds it is expired.",
      "patterns": [],
      "priority": 2.0
    },
    {
      "id": "S3",
      "description": "The biker must be able to login to the app via their email and password or by using their biometric thumb-impression. The login module must flush out user thumb impression as soon as the user has been able to login.",
      "patterns": [],
      "priority": 2.0
    },
    {
      "id": "S4",
      "description": "Biker must be logged out of the app by clicking on logout button or after an inactivity of 15 minutes to avoid unnecessary (idle) users on the app in a session.",
      "patterns": [],
      "priority": 3.0
    },
    {
      "id": "S5",
      "description": "Biker can view all of available bikes in close proximity defined by him/her such as specifying that they only want to see bikes that are available in a proximity of 100 meters.",
      "patterns": [],
      "priority": 4.0
    },
    {
      "id": "S6",
      "description": "App must help the biker to navigate to the available bike that they have selected. Upon reaching bike, biker should scan the code on bike scanner or by inputting the four digit code to register the bike for 90 minutes.",
      "patterns": [],
      "priority": 3.0
    },
    {
      "id": "S7",
      "description": "As soon as the bike is registered it must be removed from the list of available bikes.",
      "patterns": [],
      "priority": 3.0
    },
    {
      "id": "S8",
      "description": "The biker must be able to pay via their bank account or by their debit/credit card. Currently cash payments are not supported.",
      "patterns": [],
      "priority": 2.0
    },
    {
      "id": "S9",
      "description": "The app must notify the biker X minutes prior to the expiry of their rental time. Any overtime rides are subject to additional charges.",
      "patterns": [],
      "priority": 4.0
    },
    {
      "id": "S10",
      "description": "The biker must be able to rent a bike for specific minutes, a day or for a week at maximum.",
      "patterns": [],
      "priority": 4.0
    },
    {
      "id": "S11",
      "description": "The app allows the biker to view and download their bike usage history up to last 3 months in the form.",
      "patterns": [],
      "priority": 5.0
    },
    {
      "id": "S12",
      "description": "The bike administrator is able to view all of the bikes in the city as available or under utilization.",
      "patterns": [],
      "priority": 6.0
    },
    {
      "id": "S13",
      "description": "The administrator must be able to do an hourly and daily usage of the bikes.",
      "patterns": [],
      "priority": 6.0
    }
  ]
}

