          "rationale": "There is a separate BFF for each of the mobile, web and administrator clients behind one gateway.",
          "evidence": [
            "alternatives.json A3 description: 'separate backends for frontend serve the mobile app ..., the web app and the administrator console'"
          ]
        },
        {
          "driver": "Bike location and availability tracking",
          "status": "partially_satisfied",
          "rationale": "The fleet service maintains the proximity and fleet-status views. Availability changes depend on saga steps and may be compensated, so the reflected state is eventually consistent.",
          "evidence": [
            "alternatives.json A3 limitations: 'Bike registration consistency (S7) depends on correctly designed saga steps'"
          ]
        },
        {
          "driver": "Bike registration and unlocking",
          "status": "partially_satisfied",
          "rationale": "Unlock is modelled as a saga step with compensation. The unlock mechanism (S1-G55) and the required failure behaviour (S1-G23) are unstated.",
          "evidence": [
            "alternatives.json A3 description: 'compensating actions for failed unlock or payment'",
            "stage2_assumptions_gaps.json S2-G10"
          ]
        },
        {
          "driver": "Consistent bike and rental state",
          "status": "partially_satisfied",
          "rationale": "Sagas and idempotent handlers provide consistency, not single transactions. Intermediate states such as payment pending are assumed acceptable (S2-G7).",
          "evidence": [
            "alternatives.json A3 assumptions: 'Eventual consistency during a rental start or end ... is acceptable, provided double registration of a bike is prevented by the fleet service.'"
          ]
        },
        {
          "driver": "Rental lifecycle timing",
          "status": "satisfied",
          "rationale": "Event-driven rental and notification services, together with the rental-end saga, handle expiry and overtime independently of sessions.",
          "evidence": [
            "alternatives.json A3 addressed_drivers: 'Rental lifecycle timing'",
            "alternatives.json A3 description: 'rental end: release the bike, compute and collect overtime'"
          ]
        },
        {
          "driver": "Biker authentication and session management",
          "status": "partially_satisfied",
          "rationale": "The identity service, access tokens and the mobile BFF handle biometric login. Enforcement of logout and inactivity at the gateway is not described, and biometric matching is unresolved (S1-G9).",
          "evidence": [
            "alternatives.json A3 description: 'validating access tokens'",
            "stage1_assumptions_gaps.json S1-G9"
          ]
        },
        {
          "driver": "External SMS and email delivery",
          "status": "satisfied",
          "rationale": "The notification service uses adapters to SMS/email providers.",
          "evidence": [
            "alternatives.json A3 description: 'notification ... services integrate with external ... providers ... through ports and adapters'"
          ]
        },
        {
          "driver": "Usage history and administrative reporting",
          "status": "satisfied",
          "rationale": "The reporting service's CQRS read models cover S11 and S13, and the fleet service's view covers S12.",
          "evidence": [
            "alternatives.json A3 description: 'A reporting service maintains CQRS read models built from events for S11 history and S13 hourly/daily usage'"
          ]
        },
        {
          "driver": "Usability for all riders",
          "status": "partially_satisfied",
          "rationale": "BFFs allow client-tailored APIs. Navigation help (S6) is not described.",
          "evidence": [
            "alternatives.json A3 addressed_drivers: 'Usability for all riders'",
            "S6: 'App must help the biker to navigate to the available bike'"
          ]
        },
        {
          "driver": "Changeability of payment options and regulations",
          "status": "satisfied",
          "rationale": "Payment and region-dependent compliance capabilities can be deployed independently, under assumption S2-G6.",
          "evidence": [
            "alternatives.json A3 rationale: 'can change and be released independently'"
          ]
        },
        {
          "driver": "Permitted technology context",
          "status": "satisfied",
          "rationale": "All runtime technologies A3 uses are in the permitted list.",
          "evidence": [
            "alternatives.json A3 rationale: 'All runtime technologies used (orchestration, registry and discovery, gateway, broker, tracing) are in the permitted technology context.'"
          ]
        },
        {
          "driver": "Sustainable mobility goal",
          "status": "unclear",
          "rationale": "A3 does not claim to address this goal, which has no target and an unresolved meaning (S1-G65).",
          "evidence": [
            "alternatives.json A3 addressed_drivers does not include 'Sustainable mobility goal'",
            "stage1_assumptions_gaps.json S1-G65"
          ]
        }
      ]
    }
  ]
}

