2	  "$schema": "https://json-schema.org/draft/2020-12/schema",
3	  "$id": "sara-stage-artifacts.schema.json",
4	  "title": "SARA intermediate artifact shapes (harness reference)",
5	  "description": "Declarative shapes derived from the 'Expected Output' sections of the SARA stage SKILL.md files, plus the harness gap register. Used by the sara-contract-reviewer as a reading reference. Enumerations marked as harness additions narrow free-text values the source left open.",
6	  "$defs": {
7	    "stringList": { "type": "array", "items": { "type": "string" } },
8	    "priority": { "type": "string", "enum": ["high", "medium", "low"] },
9	    "satisfaction": { "type": "string", "enum": ["satisfied", "partially_satisfied", "not_satisfied", "unclear"] },
10	
11	    "requirements_analysis": {
12	      "type": "object",
13	      "required": ["requirements", "cross_requirement_relationships"],
14	      "properties": {
15	        "requirements": {
16	          "type": "array", "minItems": 1,
17	          "items": {
18	            "type": "object",
19	            "required": ["requirement_id", "requirement_description", "implicit_behaviors", "ambiguities"],
20	            "properties": {
21	              "requirement_id": { "type": "string", "minLength": 1 },
22	              "requirement_description": { "type": "string", "minLength": 1 },
23	              "implicit_behaviors": { "$ref": "#/$defs/stringList" },
24	              "ambiguities": { "$ref": "#/$defs/stringList" }
25	            }
26	          }
27	        },
28	        "cross_requirement_relationships": {
29	          "type": "array",
30	          "items": {
31	            "type": "object",
32	            "required": ["requirement_ids", "relationship_type", "description", "evidence"],
33	            "properties": {
34	              "requirement_ids": { "type": "array", "minItems": 1, "items": { "type": "string" } },
35	              "relationship_type": { "type": "string", "description": "Harness enumeration: dependency | overlap | conflict | shared_concern | inconsistency | shared_data | shared_functionality" },
36	              "description": { "type": "string" },
37	              "evidence": { "$ref": "#/$defs/stringList" }
38	            }
39	          }
40	        }
41	      }
42	    },
43	
44	    "quality_attributes": {
45	      "type": "object",
46	      "required": ["quality_attributes"],
47	      "properties": {
48	        "quality_attributes": {
49	          "type": "array",
50	          "items": {
51	            "type": "object",
52	            "required": ["name", "description", "rationale", "source_requirement_ids", "evidence", "priority"],
53	            "properties": {
54	              "name": { "type": "string" }, "description": { "type": "string" }, "rationale": { "type": "string" },
55	              "source_requirement_ids": { "$ref": "#/$defs/stringList" },
56	              "evidence": { "$ref": "#/$defs/stringList" },
57	              "priority": { "$ref": "#/$defs/priority" }
58	            }
59	          }
60	        }
61	      }
62	    },
63	
64	    "drivers": {
65	      "type": "object",
66	      "required": ["drivers"],
67	      "properties": {
68	        "drivers": {
69	          "type": "array", "minItems": 1,
70	          "items": {
71	            "type": "object",
72	            "required": ["name", "description", "driver_type", "priority", "source_requirement_ids", "supporting_evidence"],
73	            "properties": {
74	              "name": { "type": "string", "minLength": 1 }, "description": { "type": "string" },
75	              "driver_type": { "type": "string", "enum": ["functional_requirement", "quality_attribute", "constraint", "integration_concern", "business_concern", "technical_concern"] },
76	              "priority": { "$ref": "#/$defs/priority" },
77	              "source_requirement_ids": { "$ref": "#/$defs/stringList" },
78	              "supporting_evidence": { "$ref": "#/$defs/stringList" }
79	            }
80	          }
81	        }
82	      }
83	    },
84	
85	    "pattern_candidates": {
86	      "type": "object",
87	      "required": ["pattern_candidates"],
88	      "properties": {
89	        "pattern_candidates": {
90	          "type": "array", "minItems": 1,
91	          "items": {
92	            "type": "object",
93	            "required": ["pattern_name", "description", "addressed_concerns", "source_requirement_ids", "source_driver_names", "rationale", "limitations"],
94	            "properties": {
95	              "pattern_name": { "type": "string" }, "description": { "type": "string" },
96	              "addressed_concerns": { "$ref": "#/$defs/stringList" },
97	              "source_requirement_ids": { "$ref": "#/$defs/stringList" },
98	              "source_driver_names": { "$ref": "#/$defs/stringList" },
99	              "rationale": { "type": "string" },
100	              "limitations": { "$ref": "#/$defs/stringList" }
101	            }
102	          }
103	        }
104	      }
105	    },
106	
107	    "pattern_compatibility": {
108	      "type": "object",
109	      "required": ["compatibility_analysis"],
110	      "properties": {
111	        "compatibility_analysis": {
112	          "type": "array",
113	          "items": {
114	            "type": "object",
115	            "required": ["patterns", "relationship", "rationale", "conditions", "affected_drivers"],
116	            "properties": {
117	              "patterns": { "type": "array", "minItems": 2, "items": { "type": "string" } },
118	              "relationship": { "type": "string", "description": "Harness enumeration: compatible | complementary | conflicting | redundant | dependent | conditionally_compatible" },
119	              "rationale": { "type": "string" },
120	              "conditions": { "$ref": "#/$defs/stringList" },
121	              "affected_drivers": { "$ref": "#/$defs/stringList" }
122	            }
123	          }
124	        }
125	      }
126	    },
127	
128	    "alternatives": {
129	      "type": "object",
