137	            "properties": {
138	              "alternative_id": { "type": "string", "pattern": "^A[0-9]+$" },
139	              "name": { "type": "string" }, "description": { "type": "string" },
140	              "selected_patterns": { "$ref": "#/$defs/stringList" },
141	              "addressed_drivers": { "$ref": "#/$defs/stringList" },
142	              "rationale": { "type": "string" },
143	              "assumptions": { "$ref": "#/$defs/stringList" },
144	              "limitations": { "$ref": "#/$defs/stringList" }
145	            }
146	          }
147	        }
148	      }
149	    },
150	
151	    "alternative_evaluation": {
152	      "type": "object",
153	      "required": ["evaluations"],
154	      "properties": {
155	        "evaluations": {
156	          "type": "array", "minItems": 1,
157	          "items": {
158	            "type": "object",
159	            "required": ["alternative_id", "requirement_evaluations", "quality_attribute_evaluations", "driver_evaluations"],
160	            "properties": {
161	              "alternative_id": { "type": "string" },
162	              "requirement_evaluations": { "type": "array", "items": { "type": "object",
163	                "required": ["requirement_id", "status", "rationale", "evidence"],
164	                "properties": { "requirement_id": { "type": "string" }, "status": { "$ref": "#/$defs/satisfaction" },
165	                  "rationale": { "type": "string" }, "evidence": { "$ref": "#/$defs/stringList" } } } },
166	              "quality_attribute_evaluations": { "type": "array", "items": { "type": "object",
167	                "required": ["quality_attribute", "impact", "rationale", "evidence"],
168	                "properties": { "quality_attribute": { "type": "string" },
169	                  "impact": { "type": "string", "description": "Harness enumeration: positive | neutral | negative | mixed | unclear" },
170	                  "rationale": { "type": "string" }, "evidence": { "$ref": "#/$defs/stringList" } } } },
171	              "driver_evaluations": { "type": "array", "items": { "type": "object",
172	                "required": ["driver", "status", "rationale", "evidence"],
173	                "properties": { "driver": { "type": "string" }, "status": { "$ref": "#/$defs/satisfaction" },
174	                  "rationale": { "type": "string" }, "evidence": { "$ref": "#/$defs/stringList" } } } }
175	            }
176	          }
177	        }
178	      }
179	    },
180	
181	    "trade_off_analysis": {
182	      "type": "object",
183	      "required": ["trade_offs"],
184	      "properties": {
185	        "trade_offs": {
186	          "type": "array", "minItems": 1,
187	          "items": {
188	            "type": "object",
189	            "required": ["alternative_id", "strengths", "weaknesses", "qa_tensions", "arch_tradeoff", "risks"],
190	            "properties": {
191	              "alternative_id": { "type": "string" },
192	              "strengths": { "$ref": "#/$defs/stringList" }, "weaknesses": { "$ref": "#/$defs/stringList" },
193	              "qa_tensions": { "$ref": "#/$defs/stringList" }, "arch_tradeoff": { "$ref": "#/$defs/stringList" },
194	              "risks": { "$ref": "#/$defs/stringList" }
195	            }
196	          }
197	        }
198	      }
199	    },
200	
201	    "alternative_selection": {
202	      "type": "object",
203	      "required": ["selected_alternative_id", "selection_rationale", "supporting_evidence", "key_advantages", "key_limitations", "rejected_alternatives"],
204	      "properties": {
205	        "selected_alternative_id": { "type": "string", "minLength": 1 },
206	        "selection_rationale": { "type": "string", "minLength": 1 },
207	        "supporting_evidence": { "$ref": "#/$defs/stringList" },
208	        "key_advantages": { "$ref": "#/$defs/stringList" },
209	        "key_limitations": { "$ref": "#/$defs/stringList" },
210	        "rejected_alternatives": { "type": "array", "items": { "type": "object",
211	          "required": ["alternative_id", "reason"],
212	          "properties": { "alternative_id": { "type": "string" }, "reason": { "type": "string" } } } }
213	      }
214	    },
