232	        "statement": { "type": "string", "minLength": 1 },
233	        "origin": { "type": "string" },
234	        "source_refs": { "$ref": "#/$defs/stringList" },
235	        "related_ids": { "$ref": "#/$defs/stringList" },
236	        "status": { "type": "string", "enum": ["open", "relied_upon", "noted"] },
237	        "resolution_needed": { "type": "string" }
238	      }
